# envcfg.py

import os
import tomllib


class ConfigError(Exception):
    pass


def load_config(defaults, toml_path=None, env_prefix='', env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
        except tomllib.TOMLDecodeError as e:
            raise ConfigError(f'TOML decode error: {e}')

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config = _set_nested(config, env_key, _coerce(value, config.get(env_key, None)))

    return config


def _set_nested(d, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        if k not in d:
            d[k] = {}
        d = d[k]
    d[keys[-1]] = value
    return d


def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for coercion: {type(default)}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError


def test_precedence_order():
    defaults = {'a': 1, 'b': 2}
    toml_content = b'a = 3'
    env_mapping = {'APP__B': '4'}

    with open('config.toml', 'wb') as f:
        f.write(toml_content)

    config = load_config(defaults, 'config.toml', 'APP__', env_mapping)
    assert config == {'a': 3, 'b': 4}


def test_nested_overrides():
    defaults = {'server': {'port': 8080}}
    toml_content = b'[server]\nport = 8081'
    env_mapping = {'APP__SERVER__PORT': '8082'}

    with open('config.toml', 'wb') as f:
        f.write(toml_content)

    config = load_config(defaults, 'config.toml', 'APP__', env_mapping)
    assert config == {'server': {'port': 8082}}


def test_coercion_types():
    defaults = {'a': 1, 'b': 2.0, 'c': True, 'd': 'hello'}
    env_mapping = {'APP__A': '3', 'APP__B': '4.5', 'APP__C': 'false', 'APP__D': 'world'}

    config = load_config(defaults, env_mapping=env_mapping)
    assert config == {'a': 3, 'b': 4.5, 'c': False, 'd': 'world'}


def test_error_cases():
    defaults = {'a': 1}
    toml_content = b'a = "two"'
    env_mapping = {'APP__A': 'three'}

    with open('config.toml', 'wb') as f:
        f.write(toml_content)

    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, 'config.toml', 'APP__', env_mapping)
    assert 'Unsupported type for coercion' in str(excinfo.value)


def test_missing_file():
    defaults = {'a': 1}

    config = load_config(defaults)
    assert config == {'a': 1}

